let projectLibrary=[];
function activateProject(p){stopAudio();playing=false;ended=false;project=KotobaCore.normalize(p);sceneId=project.scenes[0].id;selected=project.scenes[0].blocks[0]?.id;history=[];view='script';mode='visual';stageRenderer.reset();save();draw()}
async function loadProjectLibrary(){try{projectLibrary=await window.desktop.library('list');const el=$('#projectLibrary');if(!el)return;const card=(r,trash=false)=>`<div class="settings-card" style="margin-bottom:12px"><h3 style="margin-bottom:10px">${esc(r.title)}</h3><p class="field-note">${esc(r.path)}<br>${new Date(r.updatedAt).toLocaleString()}${r.missing?' · 文件已移动或不存在':''}</p><div class="card-actions">${trash?`<button class="btn small" data-action="library-restore" data-id="${esc(r.id)}">恢复工程</button>`:`<button class="btn primary small" data-action="library-open" data-id="${esc(r.id)}" ${r.missing?'disabled':''}>打开</button><button class="btn small" data-action="library-delete" data-id="${esc(r.id)}">删除工程</button>`}</div></div>`;const live=projectLibrary.filter(r=>!r.trashed),trash=projectLibrary.filter(r=>r.trashed);el.innerHTML=`<div style="display:flex;gap:10px;margin-bottom:20px"><button class="btn primary" data-action="library-new">＋ 新建工程</button><button class="btn" data-action="native-open">打开已有工程文件</button></div><p class="field-note">新工程保存在软件的工程库。打开并保存过的外部工程也会加入列表。删除会将工程文件移入软件回收站。</p>${live.map(r=>card(r)).join('')||'<div class="empty">还没有保存的工程，点击「新建工程」开始。</div>'}${trash.length?`<h3 style="font-size:14px;margin:25px 0 16px">工程回收站</h3>${trash.map(r=>card(r,true)).join('')}`:''}`}catch(e){notify('读取工程库失败：'+e.message)}}
async function createLibraryProject(){textDialog('新建工程','未命名工程',async name=>{try{const p=KotobaCore.normalize({id:uid(),title:name,author:'独立创作者',description:'',characters:[],assets:structuredClone(seed.assets),scenes:[{id:uid(),name:'序章',transition:'fade',duration:700,blocks:[]}]});await window.desktop.library('create',{project:p});activateProject(p);notify('工程已创建并保存到工程库')}catch(e){notify('新建失败：'+e.message)}})}
async function openLibraryProject(id){try{const r=await window.desktop.library('open',{id});const p=validateProject(JSON.parse(r.text));dialog('打开工程',`<p>载入「${esc(p.title)}」？已保存的当前工程会保留在工程库。</p>`,'打开',async()=>{await window.desktop.accept(r.path);activateProject(p)})}catch(e){notify('打开失败：'+e.message)}}
function deleteLibraryProject(id){const r=projectLibrary.find(r=>r.id===id);if(!r)return;dialog('删除工程',`<p>将工程「${esc(r.title)}」的文件移到软件回收站。可以从工程管理页恢复。</p>`,'移到回收站',async()=>{try{const result=await window.desktop.library('delete',{id});if(result.active){stopAudio();playing=false;ended=false;history=[];stageRenderer.reset();project=KotobaCore.normalize(structuredClone(seed));sceneId=project.scenes[0].id;selected=null;save()}notify('工程已移入回收站');draw()}catch(e){notify('删除失败：'+e.message)}})}
async function restoreLibraryProject(id){try{await window.desktop.library('restore',{id});notify('工程已恢复');loadProjectLibrary()}catch(e){notify('恢复失败：'+e.message)}}
async function showGameSaves(){try{const slots=await window.desktop.gameSlots('list',project.id);dialog('游戏存档 / 读取',`<p>存档记录当前工程的剧情位置。读取不会更改剧本内容。</p><div class="variant-list">${Array.from({length:6},(_,i)=>{const slot=slots[i];return `<div class="variant-row"><div class="details"><strong>存档 ${i+1} · ${esc(slot?.label||'空存档')}</strong><small>${slot?new Date(slot.updatedAt).toLocaleString():'尚无游戏进度'}</small></div><button class="btn small" type="button" data-action="save-slot" data-id="${i}" ${playing&&ended?'disabled':''}>${slot?'覆盖保存':'保存'}</button><button class="btn small" type="button" data-action="load-slot" data-id="${i}" ${slot?'':'disabled'}>读取</button></div>`}).join('')}</div>`,'关闭',()=>{});$('#modal').classList.add('wide')}catch(e){notify('读取存档失败：'+e.message)}}
async function writeGameSlot(slot){try{const s=project.scenes.find(s=>s.id===(playing?playScene:sceneId))||scene();const index=playing?playIndex:Math.max(0,s.blocks.findIndex(b=>b.id===selected));const b=s.blocks[index];if(!b){notify('当前场景没有可保存的剧情');return}await window.desktop.gameSlots('save',project.id,{slot,progress:{projectId:project.id,sceneId:s.id,blockId:b.id,index,ended:false,label:s.name+' · '+(b.text||types[b.type]).slice(0,24),updatedAt:new Date().toISOString()}});save();$('#modal').close();await showGameSaves();notify('已保存到存档 '+(slot+1))}catch(e){notify('保存失败：'+e.message)}}
async function readGameSlot(slot){try{const slots=await window.desktop.gameSlots('list',project.id);const data=slots[slot];if(!data)throw Error('这个存档为空');const s=project.scenes.find(s=>s.id===data.sceneId),index=s?.blocks.findIndex(b=>b.id===data.blockId);if(!s||index<0)throw Error('存档对应的场景或剧情块已被删除，请使用其他存档');playScene=s.id;playIndex=index;playing=true;ended=false;view='script';stageRenderer.reset();playEditorMusic(s.blocks.slice(0,index).findLast(b=>b.type==='music')?.asset);resolvePlayable();$('#modal').close();draw();notify('已读取存档 '+(slot+1))}catch(e){notify('读取失败：'+e.message)}}
const featureDraw=draw;
draw=function(){featureDraw();if(view==='projects')loadProjectLibrary()};
window.desktop?.onCommand(command=>{if(command==='projects'){view='projects';draw()}if(command==='new-library')createLibraryProject();if(command==='game-saves')showGameSaves()});
